{ id:'EXP07-GC01',section:'grammar-cloze',type:'oe',passage:'Last Saturday, the school held a charity fair. Many pupils arrived early because they (1) ______ help to arrange the stalls before the visitors came.',blankNumber:1,answer:'had to',acceptedAnswers:['had to'],skill:'modal expression in past',difficulty:2,pattern:'past obligation',commonMistake:'Using have to for a completed past event.',explanation:'The obligation existed in the past, so had to is appropriate.'},
{ id:'EXP07-GC02',section:'grammar-cloze',type:'oe',passage:'The organisers checked the stalls carefully. By nine o’clock, they (1) ______ everything in place and were ready to welcome visitors.',blankNumber:1,answer:'had put',acceptedAnswers:['had put'],skill:'past perfect',difficulty:2,pattern:'earlier past action',commonMistake:'Using put without showing which action happened first.',explanation:'Putting everything in place happened before nine o’clock, so had put is used.'},
{ id:'EXP07-GC03',section:'grammar-cloze',type:'oe',passage:'Some visitors asked whether they (1) ______ pay by card, while others preferred to use cash.',blankNumber:1,answer:'could',acceptedAnswers:['could'],skill:'reported questions',difficulty:3,pattern:'could in reported question',commonMistake:'Using can after a past reporting verb.',explanation:'After asked in the past, could is used to report the ability or possibility.'},
{ id:'EXP07-GC04',section:'grammar-cloze',type:'oe',passage:'The fair ended successfully. Everyone was tired, but the pupils were proud because they (1) ______ raised enough money to support the chosen cause.',blankNumber:1,answer:'had',acceptedAnswers:['had'],skill:'past perfect',difficulty:2,pattern:'had + past participle',commonMistake:'Using have because the result is still important.',explanation:'The money had already been raised by the time the fair ended.'},

{ id:'EXP07-E01',section:'editing',type:'oe',sentence:'The group of pupils were waiting outside the laboratory.',answer:'was',wrong:'were',correct:'was',skill:'subject-verb agreement',difficulty:2,pattern:'collective noun phrase',commonMistake:'Matching the verb with pupils instead of group.',explanation:'The subject is group, which is singular in this sentence.'},
{ id:'EXP07-E02',section:'editing',type:'oe',sentence:'Mum reminded me to bring my umbrella because it look like rain.',answer:'looked',wrong:'look',correct:'looked',skill:'tenses',difficulty:2,pattern:'past reporting context',commonMistake:'Keeping the present tense after a past reporting verb.',explanation:'The sentence describes what the weather appeared to be like at that past time.'},
{ id:'EXP07-E03',section:'editing',type:'oe',sentence:'The children were excited about visit the new science centre.',answer:'visiting',wrong:'visit',correct:'visiting',skill:'gerunds',difficulty:2,pattern:'about + gerund',commonMistake:'Using the base form after a preposition.',explanation:'About is a preposition and is followed by a gerund: about visiting.'},
{ id:'EXP07-E04',section:'editing',type:'oe',sentence:'Neither of the answers are correct.',answer:'is',wrong:'are',correct:'is',skill:'subject-verb agreement',difficulty:2,pattern:'neither of + singular verb',commonMistake:'Agreeing with answers instead of neither.',explanation:'Neither is singular here, so the verb should be is.'},
{ id:'EXP07-E05',section:'editing',type:'oe',sentence:'She has went to the library to return the books.',answer:'gone',wrong:'went',correct:'gone',skill:'verb forms',difficulty:2,pattern:'has + past participle',commonMistake:'Using simple past after has.',explanation:'The present perfect requires has + past participle: has gone.'},
{ id:'EXP07-E06',section:'editing',type:'oe',sentence:'The teacher asked the pupils to worked quietly while she marked the papers.',answer:'work',wrong:'worked',correct:'work',skill:'verb patterns',difficulty:2,pattern:'to + base verb',commonMistake:'Using a past-tense verb after to.',explanation:'The infinitive structure is to work, not to worked.'},
{ id:'EXP07-E07',section:'editing',type:'oe',sentence:'There were much noise coming from the hall.',answer:'was',wrong:'were',correct:'was',skill:'quantifiers and agreement',difficulty:3,pattern:'much + uncountable noun',commonMistake:'Treating noise as a plural countable noun.',explanation:'Noise is uncountable, so use much noise and the singular verb was.'},
{ id:'EXP07-E08',section:'editing',type:'oe',sentence:'Jason is one of the pupils who enjoys taking part in school competitions.',answer:'enjoy',wrong:'enjoys',correct:'enjoy',skill:'relative clauses',difficulty:3,pattern:'one of those who agreement',commonMistake:'Making the verb agree with one instead of pupils.',explanation:'Who refers to pupils, so the relative-clause verb is plural: pupils who enjoy.'},

{ id:'EXP07-S01',section:'synthesis',type:'oe',sourceSentences:['The suitcase was very heavy.','Lina could not lift it by herself.'],starter:'The suitcase was too',answerContinuation:'heavy for Lina to lift by herself.',acceptedAnswers:['heavy for Lina to lift by herself.','heavy for Lina to lift it by herself.'],patternFamily:'too...to',pattern:'too + adjective + for + person + to-infinitive',skill:'meaning transformation',difficulty:2,commonMistake:'Changing the meaning by removing the person who could not perform the action.',explanation:'Use too + adjective + for + person + to-infinitive while keeping the original meaning.'},
{ id:'EXP07-S02',section:'synthesis',type:'oe',sourceSentences:['The rain was heavy.','The match continued as planned.'],starter:'Although',answerContinuation:'the rain was heavy, the match continued as planned.',acceptedAnswers:['the rain was heavy, the match continued as planned.','the rain was heavy, the match continued as planned'],patternFamily:'although',pattern:'although + contrast clause',skill:'conjunction transformation',difficulty:2,commonMistake:'Changing the second clause or reversing the meaning.',explanation:'Although introduces the contrast while preserving both original facts.'},
{ id:'EXP07-S03',section:'synthesis',type:'oe',sourceSentences:['The path was slippery.','The hikers walked slowly.'],starter:'As',answerContinuation:'the path was slippery, the hikers walked slowly.',acceptedAnswers:['the path was slippery, the hikers walked slowly.','the path was slippery, the hikers walked slowly'],patternFamily:'cause and effect',pattern:'as + cause, effect',skill:'conjunction transformation',difficulty:2,commonMistake:'Writing the effect as the cause.',explanation:'As can introduce the reason for an action. Keep the cause and result unchanged.'},
{ id:'EXP07-S04',section:'synthesis',type:'oe',sourceSentences:['“I will return the book tomorrow,” said Farid.'],starter:'Farid said that',answerContinuation:'he would return the book the next day.',acceptedAnswers:['he would return the book the next day.','he would return the book the next day'],patternFamily:'reported speech',pattern:'said that + backshifted tense + time expression',skill:'reported speech',difficulty:3,commonMistake:'Keeping will and tomorrow unchanged in reported speech.',explanation:'Will changes to would and tomorrow changes to the next day when the reporting verb is in the past.'},
{ id:'EXP07-S05',section:'synthesis',type:'oe',sourceSentences:['No other runner in the race was as fast as Priya.'],starter:'Priya was',answerContinuation:'the fastest runner in the race.',acceptedAnswers:['the fastest runner in the race.','the fastest runner in the race'],patternFamily:'superlative',pattern:'not as...as to superlative',skill:'comparison transformation',difficulty:2,commonMistake:'Omitting the group being compared.',explanation:'If no other runner was as fast as Priya, Priya was the fastest runner in the race.'}
